# frozen_string_literal: true

require "rails_helper"

RSpec.describe BillingFencedMailDeliveryJob, type: :job do
  # Acceptance bar: "Every invoice, line-item, invoice-tax and payment write, mobile-collection payments included,
  # gets 503 ownership_moving while handoff_step is set and writes nothing"
  # A mail job queued before the handoff and run during it must be retried, not dropped.
  it "reschedules a refused client payment mail instead of discarding it and sends nothing during the handoff" do
    ActiveJob::Base.queue_adapter = :test
    company = create(:company)
    client = create(:client, company:, email: "billing-fence-client@example.com")
    invoice = create(:invoice, client:, company:)
    TimekeepingOwnership.current.update!(handoff_step: "freeze")
    ActionMailer::Base.deliveries.clear

    job = BillingFencedMailDeliveryJob.new("ClientPaymentMailer", "payment", "deliver_now", args: [], params: { invoice_id: invoice.id })

    expect { job.perform_now }.to have_enqueued_job(BillingFencedMailDeliveryJob)
    expect(ActionMailer::Base.deliveries).to be_empty
    expect(invoice.reload.client_payment_sent_at).to be_nil
  end
end
